<template><div class="page"><header class="page-header"><div><p class="eyebrow">Inventory</p><h1 class="page-title">Vehicles</h1><p class="page-subtitle">Manage every vehicle you've purchased for parts.</p></div><button class="btn btn-primary" @click="showModal=true"><AppIcon name="plus"/>Add vehicle</button></header>
<section class="panel table-panel"><div class="toolbar"><span class="record-count">{{ vehicles.length }} {{ vehicles.length===1?'vehicle':'vehicles' }}</span></div><div v-if="loading" class="loading-state"><span class="loader"></span></div><div v-else-if="vehicles.length" class="table-wrap"><table class="data-table"><thead><tr><th>Vehicle</th><th>VIN</th><th>Total cost</th><th>Status</th><th>Purchased</th><th></th></tr></thead><tbody><tr v-for="v in vehicles" :key="v.id"><td><div class="primary-cell">{{ v.year }} {{ v.make }} {{ v.model }}</div><div class="secondary-cell">Vehicle #{{ v.id }}</div></td><td>{{ v.vin }}</td><td class="money">{{ money(Number(v.purchase_price_c)+Number(v.auction_fee_c)) }}</td><td><span class="status" :class="statusClass(v.status)">{{ pretty(v.status) }}</span></td><td>{{ date(v.purchase_date) }}</td><td><button class="btn btn-ghost btn-sm" @click="goToParts(v)">View parts <AppIcon name="arrow"/></button></td></tr></tbody></table></div><div v-else class="empty-state"><span class="empty-icon"><AppIcon name="car"/></span><h3>No vehicles yet</h3><p>Add your first vehicle to begin tracking its parts.</p></div></section>
<div v-if="showModal" class="modal-backdrop-custom" @click.self="closeModal"><form class="dialog" @submit.prevent="submitVehicle"><header class="dialog-header"><div><h2>Add a vehicle</h2><p>Record the details of your latest purchase.</p></div><button type="button" class="icon-button" @click="closeModal"><AppIcon name="close"/></button></header><div class="dialog-body form-grid"><label><span class="form-label">Make</span><input v-model="form.make" class="form-control" placeholder="Toyota" required></label><label><span class="form-label">Model</span><input v-model="form.model" class="form-control" placeholder="Camry" required></label><label><span class="form-label">Year</span><input v-model.number="form.year" type="number" min="1900" :max="new Date().getFullYear()+1" class="form-control" placeholder="2020" required></label><label><span class="form-label">VIN</span><input v-model="form.vin" class="form-control" placeholder="17-character VIN" required></label><label><span class="form-label">Purchase price ($)</span><input v-model.number="form.purchase_price_c" type="number" min="0" step=".01" class="form-control" required></label><label><span class="form-label">Auction fee ($)</span><input v-model.number="form.auction_fee_c" type="number" min="0" step=".01" class="form-control" required></label><label><span class="form-label">Status</span><select v-model="form.status" class="form-select"><option>PURCHASED</option><option>DISMANTLING</option><option>COMPLETE</option></select></label><label><span class="form-label">Purchase date</span><input v-model="form.purchase_date" type="date" class="form-control" required></label></div><footer class="dialog-footer"><button type="button" class="btn btn-ghost" @click="closeModal">Cancel</button><button class="btn btn-primary">Save vehicle</button></footer></form></div></div></template>
<script setup>import{ref,onMounted}from'vue';import superagent from'superagent';import{apiUrl}from'../api';import{useRouter}from'vue-router';import AppIcon from'../components/AppIcon.vue';const router=useRouter(),vehicles=ref([]),loading=ref(true),showModal=ref(false);const blank=()=>({make:'',model:'',year:'',vin:'',purchase_price_c:'',auction_fee_c:'',status:'PURCHASED',purchase_date:''});const form=ref(blank());const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v||0),date=v=>v?new Date(v).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—',pretty=v=>(v||'Unknown').replaceAll('_',' ').toLowerCase().replace(/^./,x=>x.toUpperCase()),statusClass=v=>['COMPLETE','SOLD'].includes(v)?'status-green':['PURCHASED','DRAFT'].includes(v)?'status-amber':'';function closeModal(){showModal.value=false;form.value=blank()}async function fetchVehicles(){loading.value=true;try{const r=await superagent.get(apiUrl('/vehicles/v1'));vehicles.value=Array.isArray(r.body)?r.body:[]}catch{vehicles.value=[]}finally{loading.value=false}}async function submitVehicle(){try{const payload={...form.value,purchase_date:new Date(form.value.purchase_date).toISOString()};await superagent.post(apiUrl('/vehicles/v1')).send(payload);await fetchVehicles();closeModal()}catch{alert('Unable to add this vehicle. Please check the details and try again.')}}function goToParts(v){router.push({path:'/parts',query:{vehicle_id:v.id}})}onMounted(fetchVehicles)</script>
